INSERT INTO configuracao.termos_de_consentimento (id, codigo, nome, texto_rascunho, base_legal_rascunho, forma_aceite_rascunho, revisado, is_deleted, created_at) VALUES ('15e00001-0000-7000-8000-000000000001'::uuid, 'VERACIDADE_DAS_INFORMACOES_DO_PEDIDO_DE_ISENCAO', 'Veracidade das informações do pedido de isenção', 'Declaro que as informações que presto neste pedido de isenção da taxa de inscrição são verdadeiras e que posso comprová-las quando solicitado. Estou ciente de que a informação falsa leva ao indeferimento do pedido, sem prejuízo das sanções legais.', 'Lei nº 12.799/2013, art. 1º; edital do processo seletivo.', 'REGISTRO_DIGITAL_COM_LOG_IP', FALSE, FALSE, '2026-10-09 00:00:00+00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO configuracao.versoes_do_termo_consentimento (id, termo_consentimento_id, numero, texto, base_legal, forma_aceite, hash, promovida_em, promovida_por) VALUES ('15e00002-0000-7000-8000-000000000001'::uuid, '15e00001-0000-7000-8000-000000000001'::uuid, 1, 'Declaro que as informações que presto neste pedido de isenção da taxa de inscrição são verdadeiras e que posso comprová-las quando solicitado. Estou ciente de que a informação falsa leva ao indeferimento do pedido, sem prejuízo das sanções legais.', 'Lei nº 12.799/2013, art. 1º; edital do processo seletivo.', 'REGISTRO_DIGITAL_COM_LOG_IP', '957ed8a21eca06a5cd160fba856175a5c548f0ad1e48c5e7df97dc352480834a', '2026-10-09 00:00:00+00'::timestamptz, 'semente-isencao-da-taxa') ON CONFLICT (id) DO NOTHING;
INSERT INTO configuracao.termos_de_consentimento (id, codigo, nome, texto_rascunho, base_legal_rascunho, forma_aceite_rascunho, revisado, is_deleted, created_at) VALUES ('15e00001-0000-7000-8000-000000000002'::uuid, 'USO_DOS_DADOS_DO_PEDIDO_DE_ISENCAO', 'Uso dos dados do pedido de isenção', 'Autorizo a Unifesspa a utilizar os dados que informo neste pedido, e os da minha inscrição, exclusivamente para a análise da isenção da taxa de inscrição deste processo seletivo.', 'Lei nº 13.709/2018 (LGPD), art. 7º, inciso I; edital do processo seletivo.', 'REGISTRO_DIGITAL_COM_LOG_IP', FALSE, FALSE, '2026-10-09 00:00:00+00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO configuracao.versoes_do_termo_consentimento (id, termo_consentimento_id, numero, texto, base_legal, forma_aceite, hash, promovida_em, promovida_por) VALUES ('15e00002-0000-7000-8000-000000000002'::uuid, '15e00001-0000-7000-8000-000000000002'::uuid, 1, 'Autorizo a Unifesspa a utilizar os dados que informo neste pedido, e os da minha inscrição, exclusivamente para a análise da isenção da taxa de inscrição deste processo seletivo.', 'Lei nº 13.709/2018 (LGPD), art. 7º, inciso I; edital do processo seletivo.', 'REGISTRO_DIGITAL_COM_LOG_IP', '67189fe097e7195fcd0f6187c49723eb5375ca2b12df45c0feeb991b89874898', '2026-10-09 00:00:00+00'::timestamptz, 'semente-isencao-da-taxa') ON CONFLICT (id) DO NOTHING;
INSERT INTO configuracao.modelos_formulario (id, codigo, nome, descricao, finalidade, tipo_processo_codigo, conteudo, ativo, created_at) VALUES ('15e00003-0000-7000-8000-000000000001'::uuid, 'ISENCAO_TAXA_INSCRICAO', 'Solicitação de isenção da taxa de inscrição', 'Pedido de isenção da taxa de inscrição pela Lei nº 12.799/2013, para qualquer processo seletivo que cobre taxa.', 'ISENCAO_TAXA', NULL, '{"titulo":"Solicita\u00E7\u00E3o de isen\u00E7\u00E3o da taxa de inscri\u00E7\u00E3o","etapas":[{"codigo":"RENDA_FAMILIAR","ordem":1,"tipo":"SECAO","bloco":null,"titulo":"Renda familiar","descricao":"A isen\u00E7\u00E3o pela Lei n\u00BA 12.799/2013 \u00E9 de quem tem renda familiar per capita de at\u00E9 um sal\u00E1rio m\u00EDnimo e meio e cursou o ensino m\u00E9dio completo em escola p\u00FAblica ou como bolsista integral em escola privada. A origem escolar \u00E9 a que voc\u00EA informou na inscri\u00E7\u00E3o.","aviso":null,"exibicao":null},{"codigo":"DOCUMENTOS","ordem":2,"tipo":"BLOCO","bloco":"COMPROVACAO_DOCUMENTAL","titulo":"Documentos","descricao":null,"aviso":null,"exibicao":null},{"codigo":"REVISAO","ordem":3,"tipo":"BLOCO","bloco":"REVISAO_E_ACEITE","titulo":"Revis\u00E3o e aceite","descricao":null,"aviso":null,"exibicao":null}],"itens":[{"fatoCodigo":"RENDA_ATE_UM_SALARIO_MINIMO_E_MEIO","ordem":1,"etapaCodigo":"RENDA_FAMILIAR","rotulo":"A renda da sua fam\u00EDlia \u00E9 de at\u00E9 um sal\u00E1rio m\u00EDnimo e meio por pessoa?","tipoRenderizacao":"BOOLEANO","formato":null,"ajuda":"Some a renda bruta mensal de todos da fam\u00EDlia e divida pelo n\u00FAmero de pessoas. Exatamente um sal\u00E1rio m\u00EDnimo e meio tamb\u00E9m d\u00E1 direito.","obrigatoriedade":{"tipo":"SEMPRE","predicado":null},"exibicao":null,"restricoes":[],"pedirConfirmacao":false,"impedimento":null}],"termos":[{"codigo":"VERACIDADE_DO_PEDIDO_DE_ISENCAO","ordem":1,"termoId":"15e00001-0000-7000-8000-000000000001","versaoId":"15e00002-0000-7000-8000-000000000001","exibicao":null,"obrigatoriedade":{"tipo":"SEMPRE","predicado":null}},{"codigo":"USO_DOS_DADOS_DO_PEDIDO_DE_ISENCAO","ordem":2,"termoId":"15e00001-0000-7000-8000-000000000002","versaoId":"15e00002-0000-7000-8000-000000000002","exibicao":null,"obrigatoriedade":{"tipo":"SEMPRE","predicado":null}}],"pressupostos":["FORMA_CONCLUSAO_EM","ONDE_CURSOU_EM"],"grupos":[],"documentosExigidos":[]}'::jsonb, TRUE, '2026-10-09 00:00:00+00'::timestamptz) ON CONFLICT (id) DO NOTHING;
